"vite build --config web/vite.config.ts\",\n    \"typecheck\": \"tsc -p web/tsconfig.json --noEmit\",\n    \"start\": \"node server/index.mjs\",\n    \"taskctl\": \"node cli/taskctl.mjs\",\n    \"test\": \"node --test && npm run test:components\",\n    \"test:components\": \"vitest run web/src/components/MarkdownDocument.test.tsx --environment jsdom\",\n    \"test:cloud\": \"node --test test/cloud-shared-worker.test.mjs\",\n    \"cloud:migrate:local\": \"wrangler d1 migrations apply codex-taskboard-db --local\",\n    \"cloud:migrate\": \"wrangler d1 migrations apply codex-taskboard-db --remote\",\n    \"cloud:deploy:dry-run\": \"npm run build:web && wrangler deploy --dry-run\",\n    \"cloud:deploy\": \"npm run build:web && wrangler deploy\",\n    \"cloud:data\": \"node scripts/migrate-to-cloud.mjs\",\n    \"check\": \"npm run typecheck && npm run build:web && npm test\"\n  },\n  \"dependencies\": {\n    \"dhtmlx-gantt\": \"^10.0.0\",\n    \"dompurify\": \"^3.4.13\",\n    \"js-yaml\": \"4.3.1\",\n    \"mdast-util-definitions\": \"^6.0.0\",\n    \"markdown-it\": \"^14.3.0\",\n    \"mermaid\": \"^11.16.1\",\n    \"micromark-util-decode-string\": \"^2.0.1\",\n    \"prosemirror-example-setup\": \"^1.2.3\",\n    \"prosemirror-inputrules\": \"^1.5.1\",\n    \"prosemirror-markdown\": \"^1.13.6\",\n    \"prosemirror-model\": \"^1.25.11\",\n    \"prosemirror-schema-list\": \"^1.5.1\",\n    \"prosemirror-state\": \"^1.4.4\",\n    \"prosemirror-view\": \"^1.42.3\",\n    \"react\": \"^19.2.7\",\n    \"react-dom\": \"^19.2.7\",\n    \"react-markdown\": \"^10.1.0\",\n    \"remark-breaks\": \"^4.0.0\",\n    \"remark-gfm\": \"^4.0.1\",\n    \"remark-parse\": \"^11.0.0\",\n    \"smol-toml\": \"^1.8.0\",\n    \"unified\": \"^11.0.5\",\n    \"ws\": \"^8.21.3\"\n  },\n  \"devDependencies\": {\n    \"@tauri-apps/cli\": \"2.11.4\",\n    \"@types/js-yaml\": \"4.0.9\",\n    \"@types/react\": \"^19.2.17\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^6.0.3\",\n  